#include <bits/stdc++.h>
using namespace std;

int read_int() {
    int x; scanf("%d", &x);
    return x;
}
vector<int> read_ints() {
    vector<int> v;
    int x;
    while (scanf("%d", &x) == 1) v.push_back(x);
    return v;
}
string read_str() {
    char buf[1024];
    scanf("%s", buf);
    return string(buf);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    n = read_int();
    mod = read_int();

    int total_edges = n * (n - 1) / 2;
    vector<vector<vector<int>>> dp(n + 1, vector<vector<int>>(total_edges + 1, vector<int>(n + 1, 0)));
    dp[1][0][1] = 1;

    for (int i = 1; i < n; i++) {
        for (int j = 0; j <= total_edges; j++) {
            for (int k = 1; k <= n; k++) {
                int val = dp[i][j][k];
                if (val == 0) continue;
                if (j + i <= total_edges) {
                    dp[i + 1][j + i][i + 1] = (dp[i + 1][j + i][i + 1] + val) % mod;
                }
                for (int l = 0; l < i; l++) {
                    int nj = j + i - 1 - l;
                    if (nj <= total_edges) {
                        dp[i + 1][nj][k] = (dp[i + 1][nj][k] + val) % mod;
                    }
                }
            }
        }
    }

    vector<vector<vector<int>>> S_dp(n + 1, vector<vector<int>>(n + 1, vector<int>(total_edges + 1, 0)));
    for (int i = 0; i <= n; i++) {
        for (int k = 0; k <= n; k++) {
            int acc = 0;
            for (int j = 0; j <= total_edges; j++) {
                acc = (acc + dp[i][j][k]) % mod;
                S_dp[i][k][j] = acc;
            }
        }
    }

    vector<vector<vector<int>>> SS_dp(n + 1, vector<vector<int>>(total_edges + 1, vector<int>(n + 1, 0)));
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= total_edges; j++) {
            int acc = 0;
            for (int k = 0; k <= n; k++) {
                acc = (acc + S_dp[i][k][j]) % mod;
                SS_dp[i][j][k] = acc;
            }
        }
    }

    vector<long long> ANS(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        long long ans = (long long)i * ANS[i - 1] % mod;
        for (int k = 0; k <= n; k++) {
            for (int j = 1; j <= total_edges; j++) {
                if (dp[i][j][k] == 0) continue;
                long long val = dp[i][j][k];
                long long sum_val = SS_dp[i][j - 1][total_edges] - SS_dp[i][j - 1][k];
                sum_val %= mod;
                if (sum_val < 0) sum_val += mod;
                ans = (ans + val * sum_val) % mod;
            }
        }
        ANS[i] = ans;
    }

    printf("%lld\n", ANS[n]);
    return 0;
}
